import torch

@torch.no_grad()
def accuracy(model, loader, device="cpu"):
    model.eval(); correct = total = 0
    for x, y in loader:
        pred = model(x.to(device)).argmax(1).cpu()
        correct += (pred == y).sum().item(); total += y.numel()
    return correct / total
